{
  "vulnerabilidade_identificada": "Cross-site scripting (XSS) armazenado por meio do conteúdo de legendas inserido diretamente em um elemento <script>.",
  "causa_da_vulnerabilidade": "O conteúdo das legendas é obtido de um arquivo configurável e concatenado sem codificação no HTML retornado. Como o elemento é um script executável, uma legenda que contenha código JavaScript pode ser executada no navegador.",
  "estrategia_de_correcao": "Codificar o conteúdo das legendas como entidades HTML antes de inseri-lo no documento, impedindo que caracteres fornecidos pelo conteúdo sejam interpretados como marcação ou código executável.",
  "edicoes": [
    {
      "arquivo": "routes/videoHandler.ts",
      "trecho_original": "      compiledTemplate = compiledTemplate.replace('<script id=\"subtitle\"></script>', '<script id=\"subtitle\" type=\"text/vtt\" data-label=\"English\" data-lang=\"en\">' + subs + '</script>')",
      "trecho_corrigido": "      compiledTemplate = compiledTemplate.replace('<script id=\"subtitle\"></script>', '<script id=\"subtitle\" type=\"text/vtt\" data-label=\"English\" data-lang=\"en\">' + entities.encode(subs) + '</script>')"
    }
  ],
  "justificativa_tecnica": "A codificação transforma caracteres como < e > em entidades HTML, evitando que conteúdo de legenda seja interpretado como uma tag <script> adicional. A alteração é localizada e mantém o fluxo e a estrutura existentes.",
  "limitacoes_da_correcao": "A codificação HTML pode alterar a representação do conteúdo VTT consumido pelo cliente. A correção impede a interpretação de marcação injetada no HTML, mas não substitui validação de formato e origem das legendas."
}
